import React, { useState } from 'react';
import { Pagination } from '@/components';

function ControlledPagination() {
  const [page, setPage] = useState(4);

  return (
    <Pagination 
      totalPages={20}
      currentPage={page} 
      onChange={(p) => setPage(p)} 
    />
  );
}
        `
